const findingsTrends = `-- name: FindingsTrends :many
WITH capped AS MATERIALIZED (
    SELECT s.id, s.service_id, s.kind, s.ref, s.scanned_at, s.gitlab_pipeline_id, s.commit_sha, s.artifact_name, s.artifact_key,
           s.count_critical, s.count_high, s.count_medium, s.count_low, s.count_unknown, s.count_fixable,
           count(*) OVER () AS window_total
    FROM scans s
    WHERE s.service_id = $1 AND ($2::boolean OR s.ref = $3) AND s.scanned_at >= $4
    ORDER BY s.scanned_at DESC, s.id DESC
    LIMIT $5
), win AS MATERIALIZED (
    SELECT c.id, c.service_id, c.kind, c.ref, c.scanned_at, c.gitlab_pipeline_id, c.commit_sha, c.artifact_name, c.artifact_key, c.count_critical, c.count_high, c.count_medium, c.count_low, c.count_unknown, c.count_fixable, c.window_total,
           lag(c.id) OVER (PARTITION BY c.ref, c.artifact_key, c.kind ORDER BY c.scanned_at, c.id) AS prev_in_window
    FROM capped c
), pairs AS MATERIALIZED (
    SELECT w.id, w.kind, COALESCE(w.prev_in_window, (
               SELECT p.id FROM scans p
               WHERE p.service_id = w.service_id AND p.ref = w.ref
                 AND p.artifact_key = w.artifact_key AND p.kind = w.kind
                 AND (p.scanned_at, p.id) < (w.scanned_at, w.id)
               ORDER BY p.scanned_at DESC, p.id DESC
               LIMIT 1)) AS prev_id
    FROM win w
), keys AS MATERIALIZED (
    SELECT v.scan_id, v.vuln_id, v.pkg_name, v.target,
           min(CASE v.severity WHEN 'CRITICAL' THEN 0 WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2
                               WHEN 'LOW' THEN 3 ELSE 4 END) AS rank
    FROM vulnerabilities v
    WHERE v.scan_id = ANY(ARRAY(SELECT x.id FROM pairs x WHERE x.kind = 'image'
                                UNION SELECT y.prev_id FROM pairs y WHERE y.kind = 'image' AND y.prev_id IS NOT NULL))
      AND NOT v.suppressed
    GROUP BY v.scan_id, v.vuln_id, v.pkg_name, v.target
), added AS (
    SELECT p.id,
           count(*) FILTER (WHERE c.rank = 0) AS critical, count(*) FILTER (WHERE c.rank = 1) AS high,
           count(*) FILTER (WHERE c.rank = 2) AS medium, count(*) FILTER (WHERE c.rank = 3) AS low,
           count(*) FILTER (WHERE c.rank = 4) AS unknown
    FROM pairs p
    JOIN keys c ON c.scan_id = p.id
    LEFT JOIN keys o ON o.scan_id = p.prev_id
                    AND o.vuln_id = c.vuln_id AND o.pkg_name = c.pkg_name AND o.target = c.target
    WHERE o.scan_id IS NULL
    GROUP BY p.id
), removed AS (
    SELECT p.id, count(*) AS fixed
    FROM pairs p
    JOIN keys o ON o.scan_id = p.prev_id
    LEFT JOIN keys c ON c.scan_id = p.id
                    AND c.vuln_id = o.vuln_id AND c.pkg_name = o.pkg_name AND c.target = o.target
    WHERE c.scan_id IS NULL
    GROUP BY p.id
)
SELECT w.id, w.kind, w.ref, w.scanned_at, w.gitlab_pipeline_id, w.commit_sha, w.artifact_name, w.artifact_key,
       w.count_critical, w.count_high, w.count_medium, w.count_low, w.count_unknown, w.count_fixable,
       prev.id AS previous_scan_id,
       coalesce(a.critical, 0)::bigint AS new_critical, coalesce(a.high, 0)::bigint AS new_high,
       coalesce(a.medium, 0)::bigint AS new_medium, coalesce(a.low, 0)::bigint AS new_low,
       coalesce(a.unknown, 0)::bigint AS new_unknown, coalesce(r.fixed, 0)::bigint AS fixed,
       w.window_total::bigint AS window_total
FROM win w
JOIN pairs pr ON pr.id = w.id
LEFT JOIN scans prev ON prev.id = pr.prev_id
LEFT JOIN added a ON a.id = w.id
LEFT JOIN removed r ON r.id = w.id
ORDER BY w.scanned_at, w.id
`

type FindingsTrendsParams struct {
	ServiceID int64
	AllRefs   bool
	Ref       string
	Since     pgtype.Timestamptz
	MaxScans  int32
}

type FindingsTrendsRow struct {
	ID               int64
	Kind             string
	Ref              string
	ScannedAt        pgtype.Timestamptz
	GitlabPipelineID int64
	CommitSha        string
	ArtifactName     string
	ArtifactKey      string
	CountCritical    int32
	CountHigh        int32
	CountMedium      int32
	CountLow         int32
	CountUnknown     int32
	CountFixable     int32
	PreviousScanID   pgtype.Int8
	NewCritical      int64
	NewHigh          int64
	NewMedium        int64
	NewLow           int64
	NewUnknown       int64
	Fixed            int64
	WindowTotal      int64
}

// FindingsTrends returns the scans of a service since a time, oldest first,
// of one ref or, with @all_refs, of every ref. Each scan carries what it
// changed against the previous scan of the same ref, artifact key and kind (which
// may lie before the window): the findings it introduced, by severity, and
// the number it fixed. The keys compared are (vuln_id, pkg_name, target) of
// unsuppressed vulnerabilities, each counted once, as in the scan diff; a
// key reported with several severities counts at its most severe. A first
// scan has every finding new; secret scans change nothing here.
//
// Only the newest @max_scans scans of the window are returned, by
// (scanned_at, id) over every ref asked for; window_total on every row is
// the number of scans in the window before that cut, so the caller can say
// that older ones were left out.
//
// One statement serves the whole window. The previous scan comes from lag()
// inside the window, and from an index probe only for the first scan of each
// (ref, artifact key, kind). The keys of every scan involved are read once, by
// scan_id, and new and fixed are hash anti-joins over them, so the cost
// follows the number of findings of at most @max_scans scans and their
// predecessors, not the number of pairs times a per-pair lookup.
func (q *Queries) FindingsTrends(ctx context.Context, arg FindingsTrendsParams) ([]FindingsTrendsRow, error) {
	rows, err := q.db.Query(ctx, findingsTrends,
		arg.ServiceID,
		arg.AllRefs,
		arg.Ref,
		arg.Since,
		arg.MaxScans,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FindingsTrendsRow{}
	for rows.Next() {
		var i FindingsTrendsRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.Ref,
			&i.ScannedAt,
			&i.GitlabPipelineID,
			&i.CommitSha,
			&i.ArtifactName,
			&i.ArtifactKey,
			&i.CountCritical,
			&i.CountHigh,
			&i.CountMedium,
			&i.CountLow,
			&i.CountUnknown,
			&i.CountFixable,
			&i.PreviousScanID,
			&i.NewCritical,
			&i.NewHigh,
			&i.NewMedium,
			&i.NewLow,
			&i.NewUnknown,
			&i.Fixed,
			&i.WindowTotal,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const findingsVulnerabilityPage = `-- name: FindingsVulnerabilityPage :many
WITH hits AS MATERIALIZED (
    SELECT v.id, v.scan_id, v.target, v.class, v.pkg_type, v.pkg_name, v.pkg_path,
           v.installed_version, v.fixed_version, v.vuln_id, v.severity, v.status, v.title,
           v.primary_url, v.suppressed, v.suppression
    FROM vulnerabilities v
    WHERE v.scan_id = ANY($2::bigint[])
      AND v.id > $3
      AND ($4::boolean OR NOT v.suppressed)
      AND (cardinality($5::text[]) = 0 OR v.severity = ANY($5::text[]))
      AND ($6::boolean IS NULL OR (v.fixed_version <> '') = $6::boolean)
      AND ($7::text = ''
           OR strpos(lower(v.pkg_name), lower($7)) > 0
           OR strpos(lower(v.vuln_id), lower($7)) > 0
           OR strpos(lower(v.title), lower($7)) > 0)
)
SELECT v.id, v.scan_id, s.artifact_name, s.artifact_key, v.target, v.class, v.pkg_type, v.pkg_name, v.pkg_path,
       v.installed_version, v.fixed_version, v.vuln_id, v.severity, v.status, v.title,
       v.primary_url, v.suppressed, v.suppression
FROM hits v
JOIN scans s ON s.id = v.scan_id
ORDER BY v.id
LIMIT $1
`

type FindingsVulnerabilityPageParams struct {
	MaxRows           int32
	ScanIds           []int64
	After             int64
	IncludeSuppressed bool
	Severities        []string
	Fixable           pgtype.Bool
	Q                 string
}

type FindingsVulnerabilityPageRow struct {
	ID               int64
	ScanID           int64
	ArtifactName     string
	ArtifactKey      string
	Target           string
	Class            string
	PkgType          string
	PkgName          string
	PkgPath          string
	InstalledVersion string
	FixedVersion     string
	VulnID           string
	Severity         string
	Status           string
	Title            string
	PrimaryUrl       string
	Suppressed       bool
	Suppression      string
}

// FindingsVulnerabilityPage returns one page, by id, of the vulnerabilities of
// the given (current) scans. severities may be empty; fixable and q are
// optional filters (q is a case-insensitive substring of package, ID or title).
// The filtered rows are materialized and then sorted: without that, the
// planner may walk the primary key in id order, expecting to meet the first
// rows of the scans soon, and for a service whose scans are the newest in the
// table read every finding ever stored (half a second at four million rows).
func (q *Queries) FindingsVulnerabilityPage(ctx context.Context, arg FindingsVulnerabilityPageParams) ([]FindingsVulnerabilityPageRow, error) {
	rows, err := q.db.Query(ctx, findingsVulnerabilityPage,
		arg.MaxRows,
		arg.ScanIds,
		arg.After,
		arg.IncludeSuppressed,
		arg.Severities,
		arg.Fixable,
		arg.Q,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FindingsVulnerabilityPageRow{}
	for rows.Next() {
		var i FindingsVulnerabilityPageRow
		if err := rows.Scan(
			&i.ID,
			&i.ScanID,
			&i.ArtifactName,
			&i.ArtifactKey,
			&i.Target,
			&i.Class,
			&i.PkgType,
			&i.PkgName,
			&i.PkgPath,
			&i.InstalledVersion,
			&i.FixedVersion,
			&i.VulnID,
			&i.Severity,
			&i.Status,
			&i.Title,
			&i.PrimaryUrl,
			&i.Suppressed,
			&i.Suppression,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
